package vn.hoangminh.erp.Ht4NhanSu.controller; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import vn.hoangminh.erp.Ht4NhanSu.dto.Ht4Dto.*; import vn.hoangminh.erp.Ht4NhanSu.service.Ht4Service;
@RestController @RequestMapping("/api/ht4") @RequiredArgsConstructor public class Ht4Controller { private final Ht4Service s;
 @GetMapping("/ho-so") public List<HoSoView> ds(@RequestParam(required=false)String tuKhoa,@RequestParam(required=false)String maPhongBan,@RequestParam(required=false)String maChucVu,@RequestParam(required=false)String maTrangThai){return s.timKiem(tuKhoa,maPhongBan,maChucVu,maTrangThai);}
 @PostMapping("/ho-so") public HoSoView them(@Valid @RequestBody HoSoInput i){return s.them(i);} @PutMapping("/ho-so/{ma}") public HoSoView sua(@PathVariable String ma,@Valid @RequestBody HoSoInput i){return s.sua(ma,i);} @PutMapping("/ho-so/{ma}/trang-thai") public HoSoView tt(@PathVariable String ma,@Valid @RequestBody TrangThaiInput i){return s.trangThai(ma,i);}
 @GetMapping("/ho-so-cua-toi") public HoSoView toi(){return s.cuaToi();} @GetMapping("/ho-so/{ma}") public HoSoView chiTiet(@PathVariable String ma){return s.chiTiet(ma);}
 @PostMapping("/yeu-cau-cap-nhat") public YeuCauView yc(@Valid @RequestBody YeuCauInput i){return s.yeuCau(i);} @GetMapping("/yeu-cau-cap-nhat") public List<YeuCauView> dsYc(){return s.danhSachYeuCau();} @PostMapping("/yeu-cau-cap-nhat/{ma}/xu-ly") public YeuCauView xuLy(@PathVariable Integer ma,@Valid @RequestBody XuLyYeuCauInput i){return s.xuLyYeuCau(ma,i);}
}
